INSERT INTO `reports` VALUES (20,1290,'001/LAP-SIDEPSIL/IX/2026','2026-09-15','APRIN GUTAWA, S.Kom','Pemindaian terhadap Website Dinas Sosial Kabupaten Kubu Raya (dinsos.kuburayakab.go.id) menemukan sisipan konten ilegal berupa promosi judi online pada halaman Pengumuman dan Berita, kata kunci spam pada meta tag beranda dan halaman Profil, tautan tersembunyi menuju domain bandar-online.site, skrip yang mengalihkan pengunjung ke domain eksternal, serta dua file web shell (mini.php dan indoxploit.php) dan satu file asing (uploads/index.phtml) yang dapat diakses publik.','Website Dinas Sosial Kabupaten Kubu Raya dinyatakan TERINDIKASI disusupi pihak tidak berwenang. Keberadaan web shell menunjukkan server telah dapat dikendalikan dari luar dan dimanfaatkan untuk menyisipkan konten ilegal.','1. Nonaktifkan sementara akses publik website hingga pembersihan selesai.\n2. Hapus file mini.php, indoxploit.php, dan uploads/index.phtml, lalu periksa file lain yang berubah sejak akhir Agustus 2026.\n3. Bersihkan konten ilegal pada halaman Pengumuman, Berita, Profil, serta meta tag dan skrip pengalihan pada beranda.\n4. Ganti seluruh kredensial akses (FTP, cPanel, database, dan akun admin CMS).\n5. Perbarui CMS dan pustaka pendukung ke versi terbaru, serta nonaktifkan eksekusi PHP pada direktori uploads.\n6. Lakukan pemindaian ulang setelah perbaikan.','final','reports/report-20.pdf',NULL,'2026-09-15 06:14:11','dinsos@kuburayakab.go.id','2026-09-15 05:49:17','2026-09-30 03:07:12',NULL),(21,1321,'002/LAP-SIDEPSIL/IX/2026','2026-09-25','APRIN GUTAWA, S.Kom','Pemindaian terhadap Website Badan Pengelola Keuangan dan Aset Daerah (BPKAD) Kabupaten Kubu Raya (bpkad.kuburayakab.go.id) menemukan skrip eksternal dari domain tidak dikenal (cdn.statcounter-id.xyz) dan iframe menuju widget.statcounter-id.xyz yang dimuat pada halaman utama sejak 18 September 2026. Tidak ditemukan konten ilegal maupun file berbahaya pada server.','Website BPKAD Kabupaten Kubu Raya berstatus PERLU PEMERIKSAAN. Domain penyedia skrip belum dapat dipastikan berbahaya, namun tidak termasuk layanan resmi yang dikenal sehingga perlu diverifikasi oleh pengelola website.','1. Konfirmasi kepada pengelola website apakah skrip statistik pengunjung dari statcounter-id.xyz sengaja dipasang.\n2. Apabila tidak dikenali, hapus skrip dan iframe tersebut dari template halaman utama.\n3. Periksa riwayat perubahan template beserta akun yang melakukan perubahan pada 18 September 2026.\n4. Lakukan pemindaian ulang setelah verifikasi untuk memastikan status website.','final','reports/report-21.pdf',NULL,'2026-09-25 07:52:57','bpkad@kuburayakab.go.id','2026-09-25 07:40:16','2026-09-30 03:07:12',NULL),(22,1322,'003/LAP-SIDEPSIL/IX/2026','2026-09-28','APRIN GUTAWA, S.Kom','Pemindaian terhadap Website Dinas Pendidikan dan Kebudayaan (Disdikbud) Kabupaten Kubu Raya (disdikbud.kuburayakab.go.id) tidak menemukan konten ilegal, tautan tersembunyi, maupun file mencurigakan. Temuan yang ada hanya berupa jumlah tautan eksternal yang cukup banyak menuju layanan resmi (Dapodik, SIPD, belajar.id) dan media sosial dinas.','Website Disdikbud Kabupaten Kubu Raya dinyatakan AMAN.','1. Lanjutkan pemantauan rutin sesuai jadwal.\n2. Pastikan WordPress, tema, dan plugin selalu diperbarui.\n3. Gunakan kata sandi yang kuat dan autentikasi dua faktor untuk akun administrator.','final','reports/report-22.pdf',NULL,NULL,NULL,'2026-09-28 04:45:47','2026-09-30 03:07:12',NULL),(24,1396,'004/LAP-SIDEPSIL/XI/2026','2026-11-02','APRIN GUTAWA, S.Kom','Pemindaian terhadap Website Dinas Sosial menunjukkan penyusupan masih berlangsung sejak dilaporkan pada September 2026: promosi judi online tersisip pada halaman Pengumuman dan Berita, web shell mini.php masih dapat diakses publik, dan file asing uploads/index.phtml belum dihapus.','Website Dinas Sosial TERINDIKASI disusupi dengan skor risiko 96/100 dan memerlukan penanganan segera.','1. Nonaktifkan sementara akses publik website. 2. Hapus web shell dan file asing pada server, lalu nonaktifkan eksekusi PHP pada direktori uploads. 3. Bersihkan konten ilegal pada halaman Pengumuman dan Berita. 4. Ganti seluruh kredensial akses server dan CMS. 5. Pulihkan website dari cadangan bersih dan lakukan pemindaian ulang.','draft','reports/report-24.pdf',NULL,NULL,NULL,'2026-11-02 03:46:32','2026-09-30 03:07:12',NULL);
/*!40000 ALTER TABLE `reports` ENABLE KEYS */;
UNLOCK TABLES;

